SELECT (SELECT JSON_QUERY(COALESCE((SELECT [Id],[key],[value] FROM [settings] FOR JSON PATH,INCLUDE_NULL_VALUES),N'[]')) AS [settings],JSON_QUERY(COALESCE((SELECT [Id],[name],[category],[description],[duration],[buffer],[price],[deposit_percent],[resource_type],[active],[color],[intake] FROM [services] FOR JSON PATH,INCLUDE_NULL_VALUES),N'[]')) AS [services],JSON_QUERY(COALESCE((SELECT [Id],[service_id],[image_url],[deleted] FROM [service_metadata] FOR JSON PATH,INCLUDE_NULL_VALUES),N'[]')) AS [service_metadata],JSON_QUERY(COALESCE((SELECT [Id],[name],[title],[bio],[color],[service_ids],[hours],[active] FROM [staff] FOR JSON PATH,INCLUDE_NULL_VALUES),N'[]')) AS [staff],JSON_QUERY(COALESCE((SELECT [Id],[staff_id],[image_url] FROM [staff_metadata] FOR JSON PATH,INCLUDE_NULL_VALUES),N'[]')) AS [staff_metadata],JSON_QUERY(COALESCE((SELECT [Id],[name],[type],[active] FROM [resources] FOR JSON PATH,INCLUDE_NULL_VALUES),N'[]')) AS [resources],JSON_QUERY(COALESCE((SELECT [Id],[staff_id],[resource_id],[starts],[ends],[reason] FROM [blocks] FOR JSON PATH,INCLUDE_NULL_VALUES),N'[]')) AS [blocks],JSON_QUERY(COALESCE((SELECT [Id],[email],[name],[phone],[notes],[marketing],[created] FROM [customers] FOR JSON PATH,INCLUDE_NULL_VALUES),N'[]')) AS [customers],JSON_QUERY(COALESCE((SELECT [Id],[reference],[token_hash],[request_key],[customer_id],[starts],[ends],[status],[expires],[total],[due],[paid],[refunded],[currency],[notes],[intake],[payment_id],[payment_url],[created],[updated],[version] FROM [bookings] FOR JSON PATH,INCLUDE_NULL_VALUES),N'[]')) AS [bookings],JSON_QUERY(COALESCE((SELECT [Id],[booking_ref],[service_id],[staff_id],[resource_id],[starts],[ends],[service_name],[price],[duration],[active] FROM [allocations] FOR JSON PATH,INCLUDE_NULL_VALUES),N'[]')) AS [allocations],JSON_QUERY(COALESCE((SELECT [Id],[booking_ref],[external_id],[kind],[amount],[status],[created] FROM [payments] FOR JSON PATH,INCLUDE_NULL_VALUES),N'[]')) AS [payments],JSON_QUERY(COALESCE((SELECT [Id],[request_key],[booking_ref],[amount],[status],[provider_id],[created] FROM [refund_requests] FOR JSON PATH,INCLUDE_NULL_VALUES),N'[]')) AS [refund_requests],JSON_QUERY(COALESCE((SELECT [Id],[name],[email],[phone],[service_id],[staff_id],[preferred_date],[notes],[status],[created] FROM [waitlist] FOR JSON PATH,INCLUDE_NULL_VALUES),N'[]')) AS [waitlist],JSON_QUERY(COALESCE((SELECT [Id],[code],[percent],[ends],[active] FROM [promos] FOR JSON PATH,INCLUDE_NULL_VALUES),N'[]')) AS [promos],JSON_QUERY(COALESCE((SELECT [Id],[booking_ref],[recipient],[subject],[body],[due],[status],[attempts],[last_error],[dedupe] FROM [messages] FOR JSON PATH,INCLUDE_NULL_VALUES),N'[]')) AS [messages],JSON_QUERY(COALESCE((SELECT [Id],[booking_ref],[action],[actor],[detail],[created] FROM [audit] FOR JSON PATH,INCLUDE_NULL_VALUES),N'[]')) AS [audit],JSON_QUERY(COALESCE((SELECT [Id],[user_id],[name],[phone],[created],[updated] FROM [customer_accounts] FOR JSON PATH,INCLUDE_NULL_VALUES),N'[]')) AS [customer_accounts],JSON_QUERY(COALESCE((SELECT [Id],[booking_ref],[user_id],[created] FROM [booking_accounts] FOR JSON PATH,INCLUDE_NULL_VALUES),N'[]')) AS [booking_accounts] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER) AS snapshot;